WELLS=np.array(json.load(open(OUT+'/wells_xyz.json')))
Z=.0202
class Painter:
 def __init__(self):
  o=r.get_obs(cameras=[]);self.pos=np.array(o.meta['proprio']['now'][7:10]);self.buf=[]
 def to(self,p,secs=None,speed=.12):
  p=np.array(p);n=max(1,int(np.ceil((np.linalg.norm(p-self.pos)/speed if secs is None else secs)*20)))
  self.buf.extend([list(self.pos+(p-self.pos)*i/n)+Q for i in range(1,n+1)]);self.pos=p
 def flush(self):
  while self.buf:
   chunk=self.buf[:190];self.buf=self.buf[190:];res=submit(chunk)
  return res
 def dip(self,c):
  w=WELLS[c];self.to([*self.pos[:2],.065]);self.to([*w[:2],.065]);self.to([*w[:2],.024],speed=.08);self.to([*w[:2],.024],.35);self.to([*w[:2],.065],speed=.08)
 def stroke(self,pts,dep,speed=.04):
  self.to([*self.pos[:2],.045],speed=.08);self.to([*pts[0],.045]);self.to([*pts[0],Z-dep],speed=.055);self.to([*pts[0],Z-dep],.25)
  for p in pts[1:]:self.to([*p,Z-dep],speed=speed)
  self.to([*pts[-1],Z-dep],.2);self.to([*pts[-1],.045],speed=.07)
 def park(self):
  self.to([-.1,.26,.12]);self.flush()
