N=256
def rgb2lab(rgb):
 a=np.asarray(rgb,dtype=float)/255;a=np.where(a>.04045,((a+.055)/1.055)**2.4,a/12.92)
 a=a@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]]).T
 a/=np.array([.95047,1,1.08883]);a=np.where(a>.008856,np.cbrt(a),7.787*a+16/116)
 return np.stack([116*a[...,1]-16,500*(a[...,0]-a[...,1]),200*(a[...,1]-a[...,2])],axis=-1)
def lab2rgb(lab):
 y=(lab[...,0]+16)/116;x=y+lab[...,1]/500;z=y-lab[...,2]/200
 a=np.stack([x,y,z],-1);a=np.where(a>6/29,a**3,(a-16/116)/7.787)*[.95047,1,1.08883]
 a=a@np.linalg.inv(np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]])).T
 a=np.where(a>.0031308,1.055*np.maximum(a,0)**(1/2.4)-.055,12.92*a)
 return np.uint8(np.clip(a*255,0,255))
def prepare():
