 pal=np.array([w['rgb'] for w in json.load(open('/app/output/spec.json'))['static']['wells']['wells']])*255;pal=rgb2lab(pal)
 np.concatenate([t.ravel(),c.ravel(),pal.ravel()]).astype('float32').tofile('/app/output/planning.bin')
